(function () {
  "use strict";
  var FB_CONFIG_KEY = "firebase_config_pr_dc"; // shared sama config Firebase Rest Time Monitoring

  // ==== PETA AKSES PER EMAIL ====
  // Key = email (case-insensitive), value = array tab yang boleh diakses.
  // Tab key harus salah satu dari: "rest-time", "performance-bagger", "inbound", "outbound", "inventory-control"
  // ("outbound" = Outbound Monitoring, isinya Aging & Packer Backlog + Occupancy & Shift,
  // dua submenu itu SATU PAKET karena hidup di file outbound.html yang sama.
  // "inbound" = menu Inbound, submenu-nya LH Tracking & Forecast MP, hidup di inbound.html.
  // "inventory-control" = menu Inventory Control, submenu-nya Log Activity Usage &
  // Stock, dua-duanya SATU PAKET karena hidup di file inventory-control.html yang sama).
  // Email yang GAK ada di daftar ini otomatis dapat akses PENUH ke semua tab (default lama).
  var ACCESS_MAP = {
    "securty-swat@spx-external.com": ["rest-time"],
    "mmpalangkarayadc@gmail.com": ["outbound"]
  };
  var ALL_TABS = ["rest-time", "performance-bagger", "inbound", "odyssey", "outbound", "inventory-control"];

  // ==== DAFTAR EMAIL YANG BOLEH HAPUS DATA (tombol "Hapus" di kolom Action) ====
  // Email di luar daftar ini masih bisa LIHAT & INPUT data seperti biasa, cuma
  // tombol "Hapus"-nya bakal disembunyikan/dinonaktifkan di halaman.
  // Dipakai sama rest-time.html (modul Rest Time & Asset Usage Monitoring) DAN
  // inventory-control.html (hak Tambah/Edit/Hapus Asset di Sub Menu Stock, serta
  // hapus log di Sub Menu Log Activity Usage — pakai flag window.__authCanDelete yang sama).
  var DELETE_ALLOWED_EMAILS = [
    "pratama.daniel@spxexpress.com",
    "rizky.armanda@spxexpress.com",
    "muhammad.reza@spxexpress.com",
    "irwan.faiz@spxexpress.com",
    "muhammad.subli@spx-external.com",
    "nurmila.wati@spx-external.com",
    "dicky.porwanto@spx-external.com",
    "yoga.parera@spxexpress.com",
    "eka.prayogi@spxexpress.com",
  ];

  function getCanDelete(email) {
    var lower = (email || "").toLowerCase();
    return DELETE_ALLOWED_EMAILS.some(function (e) { return e.toLowerCase() === lower; });
  }

  function getAllowedTabs(email) {
    var lower = (email || "").toLowerCase();
    var matchKey = Object.keys(ACCESS_MAP).filter(function (k) { return k.toLowerCase() === lower; })[0];
    return matchKey ? ACCESS_MAP[matchKey].slice() : ALL_TABS.slice();
  }

  // ==== WELCOME SCREEN (nama + foto) SETELAH LOGIN SUKSES ====
  // Nama di-generate otomatis dari bagian sebelum "@" di email (format
  // firstname.lastname jadi "Firstname Lastname"). Buat email yang gak
  // ngikutin format itu (akun bersama/gmail), taruh nama custom di sini.
  var DISPLAY_NAME_MAP = {
    "mmpalangkarayadc@gmail.com": "Tim MM Palangka Raya",
    "securty-swat@spx-external.com": "Security SWAT"
  };

  // Foto welcome screen, ditanam base64 langsung di file ini (gak perlu upload
  // file gambar terpisah ke hosting). Mau ganti foto? generate ulang base64-nya
  // terus tempel di sini, ganti DI SINI AJA.
  var WELCOME_PHOTO_BASE64 = "data:image/jpeg;base64,";

  // Welcome screen cuma nongol SEKALI per sesi browser (pas pertama kali abis
  // login), biar gak keulang-ulang tiap pindah tab/halaman yang sama-sama
  // manggil auth-guard.js ini. Pakai sessionStorage biar otomatis reset kalau
  // tab/window ditutup, konsisten sama SESSION persistence auth-nya.
  var WELCOME_SHOWN_KEY = "pr_dc_welcome_shown";

  // Durasi transisi fade welcome screen (milidetik). Mau diubah? GANTI DI SINI AJA:
  // - FADE_MS = lama animasi fade IN (Login -> Selamat Datang) & fade OUT
  //   (Selamat Datang -> Dashboard). Disamain durasinya biar konsisten.
  // - HOLD_MS = lama foto+nama nongol PENUH (opacity 100%) sebelum mulai fade
  //   out, biar sempet kebaca dulu.
  var FADE_MS = 2000;
  var HOLD_MS = 1500;

  function getDisplayName(email) {
    var lower = (email || "").toLowerCase();
    var matchKey = Object.keys(DISPLAY_NAME_MAP).filter(function (k) { return k.toLowerCase() === lower; })[0];
    if (matchKey) return DISPLAY_NAME_MAP[matchKey];
    var local = (email || "").split("@")[0];
    var parts = local.split(/[._-]+/).filter(Boolean);
    if (!parts.length) return email || "";
    return parts.map(function (p) {
      return p.charAt(0).toUpperCase() + p.slice(1).toLowerCase();
    }).join(" ");
  }

  // Ganti overlay "Memeriksa akses..." jadi "Selamat Datang, <Nama>" + foto,
  // dengan efek FADE IN pas muncul & FADE OUT pas ngilang nampilin dashboard
  // (masing-masing minimal FADE_MS, di-hold HOLD_MS di tengah biar sempet
  // kebaca). callback() dipanggil pas fade out KELAR (atau langsung kalau
  // welcome screen udah pernah ditampilin sesi ini, gak ada animasi).
  function showWelcomeScreen(email, callback) {
    if (sessionStorage.getItem(WELCOME_SHOWN_KEY)) {
      callback();
      return;
    }
    sessionStorage.setItem(WELCOME_SHOWN_KEY, "1");

    overlay.style.flexDirection = "column";
    overlay.style.gap = "14px";
    // innerHTML = "" di sini dulu ikut ngapus blob dekoratifnya (karena blob itu
    // child overlay juga). Sekarang cuma hapus statusText "Memeriksa akses..."
    // doang, blob-nya tetep nempel di belakang welcome screen.
    if (statusText && statusText.parentNode === overlay) overlay.removeChild(statusText);

    // Konten welcome (foto + teks) dibungkus div sendiri, opacity mulai dari 0,
    // biar bisa di-fade-in independen dari overlay-nya (overlay-nya sendiri
    // yang belakangan di-fade-out buat transisi ke dashboard).
    var welcomeBox = document.createElement("div");
    welcomeBox.style.cssText =
      "position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;gap:14px;" +
      "opacity:0;transition:opacity " + FADE_MS + "ms ease;";

    var img = document.createElement("img");
    img.src = WELCOME_PHOTO_BASE64;
    // Ukuran foto dibikin relatif ke lebar layar (20vw = 1/5 layar), jadi gede
    // & jelas keliatan, bukan avatar kecil kayak sebelumnya (dulu 110px tetap).
    img.style.cssText =
      "width:20vw;height:20vw;border-radius:50%;object-fit:cover;" +
      "border:3px solid #e67e22;box-shadow:0 6px 24px rgba(0,0,0,0.45);";

    var greeting = document.createElement("div");
    greeting.style.cssText = "font-size:16px;font-weight:700;color:#f1f5f9;";
    greeting.textContent = "Selamat Datang, " + getDisplayName(email) + "!";

    welcomeBox.appendChild(img);
    welcomeBox.appendChild(greeting);
    overlay.appendChild(welcomeBox);

    // Paksa reflow dulu sebelum opacity diubah ke 1 — kalau nggak, browser
    // sering nge-skip transition-nya (append + ganti opacity dianggap 1 batch
    // perubahan yang sama, jadinya "muncul" langsung, bukan fade).
    void welcomeBox.offsetWidth;
    welcomeBox.style.opacity = "1"; // ▶ FADE IN mulai (Login -> Selamat Datang), durasi FADE_MS

    setTimeout(function () {
      // ▶ FADE OUT mulai (Selamat Datang -> Dashboard), durasi FADE_MS: overlay
      // pelan-pelan transparan, dashboard di baliknya (udah ke-render duluan)
      // keliatan makin jelas seiring opacity turun.
      overlay.style.transition = "opacity " + FADE_MS + "ms ease";
      overlay.style.opacity = "0";
      setTimeout(callback, FADE_MS);
    }, FADE_MS + HOLD_MS);
  }

  // Config default udah ditanam di sini, HARUS SAMA PERSIS kayak di login.html
  // (project "dashboardpalangkarayadc" — di situ tempat user-user beneran terdaftar,
  // termasuk mmpalangkarayadc@gmail.com & securty-swat@spx-external.com). Sebelumnya
  // di sini kepasang project "pr-dc-rest-monitoring" yang beda sendiri & gak punya user
  // itu, makanya walau login di login.html sukses, di sini selalu keanggep belum login
  // (session-nya nempel di project yang beda) → dilempar balik lagi ke login.html.
  // Kalau mau ganti project Firebase, ubah DI SINI DAN DI login.html SEKALIGUS.
  var DEFAULT_FB_CONFIG = {
    apiKey: "AIzaSyBn1bdUH8uRc_hFq0h4liWd8vLDOLYZFMA",
    authDomain: "dashboardpalangkarayadc.firebaseapp.com",
    databaseURL: "https://dashboardpalangkarayadc-default-rtdb.asia-southeast1.firebasedatabase.app",
    projectId: "dashboardpalangkarayadc",
    storageBucket: "dashboardpalangkarayadc.firebasestorage.app",
    messagingSenderId: "796202356400",
    appId: "1:796202356400:web:d5360896e59dcbba66f575"
  };

  // Overlay "Memeriksa akses..." biar konten gak keliatan sebelum login-nya kevalidasi.
  // Background disamain kayak tampilan login.html yang baru: foto warehouse yang
  // sama, dikasih scrim gelap di atasnya biar teks & foto welcome tetap kebaca.
  var OVERLAY_BG_BASE64 = "data:image/jpeg;base64,";
  var overlay = document.createElement("div");
  overlay.id = "authCheckOverlay";
  overlay.style.cssText =
    "position:fixed;inset:0;overflow:hidden;color:#f1f5f9;display:flex;" +
    "align-items:center;justify-content:center;font-family:'Poppins',sans-serif;" +
    "font-size:14px;font-weight:600;z-index:999999;letter-spacing:0.3px;" +
    "background-image:linear-gradient(180deg, rgba(10,16,32,0.72), rgba(10,16,32,0.72))," +
    "url('" + OVERLAY_BG_BASE64 + "');" +
    "background-size:cover;background-position:center;background-repeat:no-repeat;";

  var statusText = document.createElement("div");
  statusText.style.cssText = "position:relative;z-index:1;";
  statusText.innerText = "🔒 Memeriksa akses...";
  overlay.appendChild(statusText);
  document.body.appendChild(overlay);

  function goToLogin() {
    var redirectTo = window.location.pathname + window.location.search + window.location.hash;
    window.location.href = "login.html?redirect=" + encodeURIComponent(redirectTo);
  }

  var configRaw = localStorage.getItem(FB_CONFIG_KEY);
  // SECURITY FIX: config Firebase gak lagi dipercaya dari localStorage siapapun bisa
  // nge-poison itu (lewat "Ganti config Firebase" di login.html, atau langsung lewat
  // devtools). Sekarang SELALU pakai DEFAULT_FB_CONFIG yang ditanam di kode ini, gak
  // peduli localStorage isinya apa. Kalau memang mau pindah project Firebase, ubah
  // DEFAULT_FB_CONFIG di kode ini terus redeploy — bukan dari tampilan.
  if (configRaw) localStorage.removeItem(FB_CONFIG_KEY); // bersihin sisa config lama yang mungkin udah di-poison
  var config = DEFAULT_FB_CONFIG;

  try {
    if (!firebase.apps.length) firebase.initializeApp(config);
  } catch (e) {
    console.error("Gagal init Firebase Auth:", e);
    goToLogin();
    return;
  }

  // SESSION persistence: sesi login cuma nempel di tab ini aja, begitu tab/window
  // ditutup, sesi ilang otomatis (gak kayak default LOCAL yang tetep login walau ditutup).
  firebase.auth().setPersistence(firebase.auth.Auth.Persistence.SESSION).catch(function (e) {
    console.error("Gagal set persistence:", e);
  });

  firebase.auth().onAuthStateChanged(function (user) {
    if (user) {
      window.__authUserEmail = user.email;
      window.__authAllowedTabs = getAllowedTabs(user.email);
      window.__authCanDelete = getCanDelete(user.email);

      // window.__PAGE_TAB dideklarasi di masing-masing halaman (rest-time.html,
      // performance-bagger.html, outbound.html) SEBELUM script auth-guard.js ini
      // dipanggil. index.html (shell) gak declare ini, jadi selalu lolos ke bawah.
      var pageTab = window.__PAGE_TAB;
      if (pageTab && window.__authAllowedTabs.indexOf(pageTab) === -1) {
        // Ketauan buka halaman ini langsung (bukan lewat index.html) padahal
        // emailnya gak punya akses ke tab ini. Overlay TETAP nempel di depan
        // (gak di-remove), jadi konten/data di baliknya gak pernah keliatan.
        overlay.style.flexDirection = "column";
        overlay.style.gap = "12px";
        if (statusText && statusText.parentNode === overlay) overlay.removeChild(statusText);
        var deniedBox = document.createElement("div");
        deniedBox.style.cssText =
          "position:relative;z-index:1;display:flex;flex-direction:column;align-items:center;gap:12px;color:#f1f5f9;";
        deniedBox.innerHTML =
          "<div>🚫 Kamu gak punya akses ke halaman ini.</div>" +
          '<a href="index.html" style="font-size:12px;background:#ee2f6f;color:#fff;' +
          'padding:8px 16px;border-radius:20px;text-decoration:none;font-weight:600;">Kembali ke Beranda</a>';
        overlay.appendChild(deniedBox);
        return;
      }

      showWelcomeScreen(user.email, function () {
        overlay.remove();
        // Kasih tau index.html (shell) kalau allowedTabs udah siap dipakai buat
        // filter tombol tab & nentuin iframe mana aja yang boleh di-load.
        window.dispatchEvent(new CustomEvent("authReady", { detail: { allowedTabs: window.__authAllowedTabs } }));
      });
    } else {
      goToLogin();
    }
  });
})();

function logoutApp() {
  if (window.firebase && firebase.auth) {
    firebase.auth().signOut().finally(function () {
      window.location.href = "login.html";
    });
  } else {
    window.location.href = "login.html";
  }
}
